-- Venue Live Guest "Ulang Tahun Tangled Lantern Festival". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara tangledlantern), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'tangledlantern', 'Ulang Tahun Tangled Lantern Festival', 'tangledlantern', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 174, 'center 38%',
  $t${"name":"Tangled Lantern Festival","orn":"diamond","ui":{"ivory":"#FBF6FF","white":"#FFFFFF","soft":"#EEDDF9","soft2":"#D2B0EE","accent":"#A55FD0","deep":"#5E3786","ink":"#4A2C6C","mute":"#9884B3","line":"#E5D2F3","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FEFAFF","ink":"#4A2C6C","accent":"#A55FD0","gold":"#C9A24A","leaf":"#EEDDF9","hbg":"rgba(251,246,255,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(74,44,108,.9)","acc":"#FFE29A","on":"#4A2C6C"},"scr":{"wine":"#5E3786","veil":"251,246,255"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'tangledlantern');
